//! Federated continual knowledge-representation contract model.
//!
//! Atlas feature: `AFA-brain-P04-F08`. Only purpose-bound, signed, fresh, semantically
//! comparable aggregate artifacts may cross an institution boundary; raw study data stays local.

use bioprism_foundation::{AuthorityRequirement, AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-brain-P04-F08";
pub const CONTRACT_VERSION: &str = "brain-federated-continual-knowledge-representation-contract-model/1.0";
pub const INPUT_SCHEMA: &str = "ScopedResearchClaims1@1";
pub const OUTPUT_SCHEMA: &str = "TypedKnowledgeWorld1@1";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedKnowledgeContractPeer { pub peer_id: String, pub institution_id: String, pub endpoint: String, pub purpose: String, pub semantic_profile: String, pub freshness_epoch: u64, pub signed_approval: bool, pub permitted_artifact_digest: Option<ContentHash>, pub evidence_digest: Option<ContentHash>, pub provenance_digest: Option<ContentHash>, pub state: EvidenceState, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedKnowledgeContractRequest { pub request_id: String, pub federation_id: String, pub purpose: String, pub semantic_profile: String, pub min_freshness_epoch: u64, pub quorum_required: usize, pub peers: Vec<FederatedKnowledgeContractPeer>, pub input_schema: String, pub output_schema: String, pub source_revision: u16, pub target_revision: u16, pub migration_requested: bool, pub aggregate_only: bool, pub policy_allow: bool, pub protected_closure: bool, pub raw_data_local: bool, pub replay_identity: ContentHash, pub boundary: String }
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all="snake_case")]
pub enum FederatedKnowledgeContractDisposition { Completed, Migrated, Partial, Blocked }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FederatedKnowledgeContractReceipt { pub schema_version:String, pub contract_version:String, pub feature_id:String, pub request_id:String, pub federation_id:String, pub purpose:String, pub semantic_profile:String, pub disposition:FederatedKnowledgeContractDisposition, pub input_schema:String, pub output_schema:String, pub source_revision:u16, pub target_revision:u16, pub min_freshness_epoch:u64, pub quorum_required:usize, pub quorum_met:bool, pub candidate_order:Vec<String>, pub qualified_order:Vec<String>, pub unresolved_order:Vec<String>, pub denied_order:Vec<String>, pub stale_order:Vec<String>, pub semantic_mismatch_order:Vec<String>, pub signer_order:Vec<String>, pub exchange_order:Vec<String>, pub contract_digest:ContentHash, pub federation_digest:ContentHash, pub migration_digest:ContentHash, pub replay_identity:ContentHash, pub omissions:Vec<String>, pub uncertainty:Vec<String>, pub negative_evidence:Vec<String>, pub effect_receipts:Vec<String>, pub artifact:TypedResearchArtifact, pub raw_data_local:bool, pub boundary:String }
#[derive(Debug, Error, PartialEq, Eq)]
pub enum FederatedKnowledgeContractError { #[error("invalid federated continual knowledge contract: {0}")] Invalid(String), #[error("federated knowledge contract artifact failed: {0}")] Artifact(String) }

impl FederatedKnowledgeContractReceipt { pub fn validate(&self)->Result<(),FederatedKnowledgeContractError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.input_schema!=INPUT_SCHEMA||self.output_schema!=OUTPUT_SCHEMA||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||self.request_id.trim().is_empty()||self.federation_id.trim().is_empty()||self.purpose.trim().is_empty()||self.semantic_profile.trim().is_empty()||self.source_revision==0||self.target_revision<self.source_revision||self.quorum_required==0||self.candidate_order.is_empty()||self.effect_receipts.is_empty(){return Err(FederatedKnowledgeContractError::Invalid("federated contract identity, schemas, purpose, quorum, locality, or effects are incomplete".into()));} for values in [&self.candidate_order,&self.qualified_order,&self.unresolved_order,&self.denied_order,&self.stale_order,&self.semantic_mismatch_order,&self.signer_order,&self.exchange_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if values.windows(2).any(|p|p[0]>=p[1]){return Err(FederatedKnowledgeContractError::Invalid("federated contract ordering is not canonical".into()));}} let classified=self.qualified_order.iter().chain(self.unresolved_order.iter()).chain(self.denied_order.iter()).cloned().collect::<BTreeSet<_>>();if classified.len()!=self.candidate_order.len()||classified.iter().any(|peer|!self.candidate_order.contains(peer))||self.exchange_order.iter().any(|peer|!self.qualified_order.contains(peer)){return Err(FederatedKnowledgeContractError::Invalid("federated contract states do not partition peers".into()));}if self.quorum_met && self.qualified_order.len()<self.quorum_required{return Err(FederatedKnowledgeContractError::Invalid("federated quorum witness is inconsistent".into()));}for d in [&self.contract_digest,&self.federation_digest,&self.migration_digest,&self.replay_identity,&self.artifact.content_hash]{if d.as_str().len()!=64{return Err(FederatedKnowledgeContractError::Invalid("federated contract digest is invalid".into()));}}if self.effect_receipts.iter().any(|e|!e.starts_with("exchange:permitted-federated-knowledge:")&&e!="block:unsafe-release"){return Err(FederatedKnowledgeContractError::Invalid("federated contract effect is outside aggregate-only gate".into()));}self.artifact.validate_metadata().map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))}pub fn digest(&self)->Result<ContentHash,FederatedKnowledgeContractError>{self.validate()?;let value=serde_json::to_value(self).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))?;ContentHash::of_value(&value).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))}}

pub fn federated_continual_knowledge_representation_contract_model_manifest()->CapabilityManifest{CapabilityManifest{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),capability_id:FEATURE_ID.into(),version:CONTRACT_VERSION.into(),owner_crate:"brain".into(),consumers:["research workflow operator".into(),"federation steward".into()].into(),behavior:"qualifies fresh, signed, purpose-bound, semantically comparable peer knowledge contracts under quorum before aggregate-only exchange".into(),value:"enables continual consortium knowledge worlds without moving raw institution-local research data or hiding stale peers".into(),inputs:vec![TypedPort{name:"federated_scoped_research_claims".into(),schema:INPUT_SCHEMA.into(),required:true}],outputs:vec![TypedPort{name:"federated_typed_knowledge_world_contract".into(),schema:OUTPUT_SCHEMA.into(),required:true}],effects:[Effect::ReadLocalData,Effect::WriteLocalArtifact].into(),permissions:["read:local-research-artifacts".into(),"exchange:permitted-research-summary".into()].into(),determinism:Determinism::ByteStable,evidence:vec![EvidenceReference{source_id:"json-schema".into(),state:EvidenceState::Supported,locator:Some("https://json-schema.org/specification".into())}],authority_requirements:vec![AuthorityRequirement{role:"federation-steward".into(),reason:"signed-federation-approval".into()}],autonomy_tier:AutonomyTier::A1,surfaces:[ResearchSurface::Ui,ResearchSurface::Api,ResearchSurface::Sdk,ResearchSurface::Cli,ResearchSurface::McpTool,ResearchSurface::Policy,ResearchSurface::Operator].into(),boundary:PRECLINICAL_BOUNDARY.into()}}

pub fn model_federated_continual_knowledge_representation_contract(request:&FederatedKnowledgeContractRequest)->Result<FederatedKnowledgeContractReceipt,FederatedKnowledgeContractError>{if request.request_id.trim().is_empty()||request.federation_id.trim().is_empty()||request.purpose.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.peers.is_empty()||request.input_schema!=INPUT_SCHEMA||request.output_schema!=OUTPUT_SCHEMA||request.source_revision==0||request.target_revision<request.source_revision||(request.target_revision>request.source_revision&&!request.migration_requested)||request.quorum_required==0||request.replay_identity.as_str().len()!=64||!request.aggregate_only||!request.raw_data_local||request.boundary!=PRECLINICAL_BOUNDARY{return Err(FederatedKnowledgeContractError::Invalid("federated contract identity, schemas, purpose, quorum, migration, aggregate-only, replay, locality, or boundary is invalid".into()));}let mut peers=request.peers.clone();peers.sort_by(|a,b|a.peer_id.cmp(&b.peer_id));let candidate=peers.iter().map(|p|p.peer_id.clone()).collect::<Vec<_>>();if candidate.windows(2).any(|p|p[0]==p[1])||candidate.iter().any(|v|v.trim().is_empty()){return Err(FederatedKnowledgeContractError::Invalid("peer identifiers must be unique and non-empty".into()));}let mut qualified=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut denied=BTreeSet::new();let mut stale=BTreeSet::new();let mut mismatch=BTreeSet::new();let mut signers=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::from(["gate:purpose-bound-exchange".to_string(),"gate:aggregate-only".to_string(),"gate:raw-data-locality".to_string(),"gate:unknown-is-not-asserted".to_string()]);let mut negative=BTreeSet::new();for peer in &peers{if !request.policy_allow||!request.protected_closure||peer.boundary!=PRECLINICAL_BOUNDARY||peer.purpose!=request.purpose||peer.institution_id.trim().is_empty()||peer.endpoint.trim().is_empty(){denied.insert(peer.peer_id.clone());negative.insert(format!("peer:{}:scope-policy-purpose",peer.peer_id));}else if peer.freshness_epoch<request.min_freshness_epoch{unresolved.insert(peer.peer_id.clone());stale.insert(peer.peer_id.clone());omissions.insert(format!("peer:{}:stale",peer.peer_id));}else if peer.semantic_profile!=request.semantic_profile{unresolved.insert(peer.peer_id.clone());mismatch.insert(peer.peer_id.clone());uncertainty.insert(format!("peer:{}:semantic-profile-mismatch",peer.peer_id));}else if !peer.signed_approval||peer.permitted_artifact_digest.is_none(){unresolved.insert(peer.peer_id.clone());if !peer.signed_approval{signers.insert(peer.peer_id.clone());}omissions.insert(format!("peer:{}:signed-permitted-artifact-missing",peer.peer_id));}else if peer.evidence_digest.is_none()||peer.provenance_digest.is_none(){unresolved.insert(peer.peer_id.clone());omissions.insert(format!("peer:{}:evidence-or-provenance-missing",peer.peer_id));}else if matches!(peer.state,EvidenceState::Unknown|EvidenceState::Speculative){unresolved.insert(peer.peer_id.clone());uncertainty.insert(format!("peer:{}:unknown-not-asserted",peer.peer_id));}else if matches!(peer.state,EvidenceState::Contradicted){denied.insert(peer.peer_id.clone());negative.insert(format!("peer:{}:contradicted",peer.peer_id));}else{qualified.insert(peer.peer_id.clone());}}if !request.policy_allow{omissions.insert("control:policy-denied".into());}if !request.protected_closure{omissions.insert("control:protected-closure-incomplete".into());}let quorum_met=qualified.len()>=request.quorum_required; if !quorum_met {omissions.insert(format!("control:quorum-not-met:{}-of-{}",qualified.len(),request.quorum_required));}if request.target_revision>request.source_revision{uncertainty.insert(format!("migration:{}-to-{}",request.source_revision,request.target_revision));}let exchange=if quorum_met{qualified.clone()}else{BTreeSet::new()};let federation_digest=ContentHash::of_value(&json!({"federation_id":request.federation_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"qualified_order":qualified,"quorum_required":request.quorum_required,"min_freshness_epoch":request.min_freshness_epoch})).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))?;let contract_digest=ContentHash::of_value(&json!({"candidate_order":candidate,"qualified_order":qualified,"unresolved_order":unresolved,"denied_order":denied,"stale_order":stale,"semantic_mismatch_order":mismatch,"signer_order":signers,"federation_digest":federation_digest})).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))?;let migration_digest=ContentHash::of_value(&json!({"source_revision":request.source_revision,"target_revision":request.target_revision,"migration_requested":request.migration_requested})).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))?;let disposition=if !request.policy_allow||!request.protected_closure||!request.aggregate_only||!request.raw_data_local{FederatedKnowledgeContractDisposition::Blocked}else if !quorum_met||!unresolved.is_empty()||!denied.is_empty(){FederatedKnowledgeContractDisposition::Partial}else if request.target_revision>request.source_revision{FederatedKnowledgeContractDisposition::Migrated}else{FederatedKnowledgeContractDisposition::Completed};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.request_id,"federation_id":request.federation_id,"purpose":request.purpose,"semantic_profile":request.semantic_profile,"disposition":disposition,"input_schema":INPUT_SCHEMA,"output_schema":OUTPUT_SCHEMA,"source_revision":request.source_revision,"target_revision":request.target_revision,"quorum_met":quorum_met,"federation_digest":federation_digest,"contract_digest":contract_digest,"migration_digest":migration_digest,"replay_identity":request.replay_identity,"boundary":PRECLINICAL_BOUNDARY});let artifact=TypedResearchArtifact::from_payload(format!("brain-federated-knowledge-contract:{}",request.request_id),"application/vnd.aurora.typed-knowledge-world+json",&payload,Vec::new(),Vec::new()).map_err(|e|FederatedKnowledgeContractError::Artifact(e.to_string()))?;let receipt=FederatedKnowledgeContractReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:request.request_id.clone(),federation_id:request.federation_id.clone(),purpose:request.purpose.clone(),semantic_profile:request.semantic_profile.clone(),disposition,input_schema:INPUT_SCHEMA.into(),output_schema:OUTPUT_SCHEMA.into(),source_revision:request.source_revision,target_revision:request.target_revision,min_freshness_epoch:request.min_freshness_epoch,quorum_required:request.quorum_required,quorum_met,candidate_order:candidate,qualified_order:qualified.into_iter().collect(),unresolved_order:unresolved.into_iter().collect(),denied_order:denied.into_iter().collect(),stale_order:stale.into_iter().collect(),semantic_mismatch_order:mismatch.into_iter().collect(),signer_order:signers.into_iter().collect(),exchange_order:exchange.into_iter().collect(),contract_digest,federation_digest,migration_digest,replay_identity:request.replay_identity.clone(),omissions:omissions.into_iter().collect(),uncertainty:uncertainty.into_iter().collect(),negative_evidence:negative.into_iter().collect(),effect_receipts:if quorum_met&&!matches!(disposition,FederatedKnowledgeContractDisposition::Blocked){vec![format!("exchange:permitted-federated-knowledge:{}",request.request_id)]}else{vec!["block:unsafe-release".into()]},artifact,raw_data_local:request.raw_data_local,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}

#[cfg(test)]mod tests{use super::*;fn hash(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn request()->FederatedKnowledgeContractRequest{let h=hash("federated-contract");let peer=|id:&str|FederatedKnowledgeContractPeer{peer_id:id.into(),institution_id:format!("inst:{id}"),endpoint:format!("https://{id}"),purpose:"knowledge-world".into(),semantic_profile:"profile:v1".into(),freshness_epoch:10,signed_approval:true,permitted_artifact_digest:Some(h.clone()),evidence_digest:Some(h.clone()),provenance_digest:Some(h.clone()),state:EvidenceState::Supported,boundary:PRECLINICAL_BOUNDARY.into()};FederatedKnowledgeContractRequest{request_id:"request:federated-contract".into(),federation_id:"fed:one".into(),purpose:"knowledge-world".into(),semantic_profile:"profile:v1".into(),min_freshness_epoch:5,quorum_required:2,peers:vec![peer("peer:a"),peer("peer:b"),peer("peer:c")],input_schema:INPUT_SCHEMA.into(),output_schema:OUTPUT_SCHEMA.into(),source_revision:1,target_revision:1,migration_requested:false,aggregate_only:true,policy_allow:true,protected_closure:true,raw_data_local:true,replay_identity:h,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn manifest_is_a1(){assert_eq!(federated_continual_knowledge_representation_contract_model_manifest().autonomy_tier,AutonomyTier::A1);}#[test]fn quorum_completes(){let r=model_federated_continual_knowledge_representation_contract(&request()).unwrap();assert_eq!(r.disposition,FederatedKnowledgeContractDisposition::Completed);assert!(r.quorum_met);}#[test]fn stale_peer_is_unresolved(){let mut v=request();v.peers[0].freshness_epoch=1;let r=model_federated_continual_knowledge_representation_contract(&v).unwrap();assert!(r.stale_order.contains(&"peer:a".to_string()));assert_eq!(r.disposition,FederatedKnowledgeContractDisposition::Partial);}#[test]fn semantic_mismatch_is_unresolved(){let mut v=request();v.peers[0].semantic_profile="profile:v2".into();let r=model_federated_continual_knowledge_representation_contract(&v).unwrap();assert!(r.semantic_mismatch_order.contains(&"peer:a".to_string()));}#[test]fn signer_gap_is_unresolved(){let mut v=request();v.peers[0].signed_approval=false;let r=model_federated_continual_knowledge_representation_contract(&v).unwrap();assert!(r.signer_order.contains(&"peer:a".to_string()));}#[test]fn quorum_failure_blocks_exchange(){let mut v=request();v.quorum_required=4;let r=model_federated_continual_knowledge_representation_contract(&v).unwrap();assert!(!r.quorum_met);assert_eq!(r.effect_receipts,vec!["block:unsafe-release"]);}#[test]fn policy_blocks(){let mut v=request();v.policy_allow=false;assert_eq!(model_federated_continual_knowledge_representation_contract(&v).unwrap().disposition,FederatedKnowledgeContractDisposition::Blocked);}#[test]fn digest_is_stable(){let r=model_federated_continual_knowledge_representation_contract(&request()).unwrap();assert_eq!(r.digest().unwrap(),r.digest().unwrap());}}
